'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const B = nextInt();
const edges = new Array(B);

for (let i = 0; i < B; i++) {
  edges[i] = [nextInt() - 1, nextInt() - 1, nextInt()];
}

edges.sort((a, b) => b[2] - a[2]);

const dsuParent = new Int32Array(N);
const dsuSize = new Int32Array(N);
for (let i = 0; i < N; i++) {
  dsuParent[i] = i;
  dsuSize[i] = 1;
}

function find(x) {
  let root = x;
  while (dsuParent[root] !== root) root = dsuParent[root];
  while (dsuParent[x] !== x) {
    const next = dsuParent[x];
    dsuParent[x] = root;
    x = next;
  }
  return root;
}

const head = new Int32Array(N);
head.fill(-1);
const to = new Int32Array(2 * B);
const next = new Int32Array(2 * B);
const weight = new Int32Array(2 * B);
let edgeCount = 0;

function addEdge(u, v, w) {
  to[edgeCount] = v;
  weight[edgeCount] = w;
  next[edgeCount] = head[u];
  head[u] = edgeCount++;
}

let selected = 0;
for (const [u, v, w] of edges) {
  let ru = find(u);
  let rv = find(v);
  if (ru !== rv) {
    if (dsuSize[ru] < dsuSize[rv]) {
      const tmp = ru;
      ru = rv;
      rv = tmp;
    }
    dsuParent[rv] = ru;
    dsuSize[ru] += dsuSize[rv];

    addEdge(u, v, w);
    addEdge(v, u, w);
    if (++selected === N - 1) break;
  }
}

let LOG = 1;
while ((1 << LOG) <= N) LOG++;

const depth = new Int32Array(N);
const up = new Array(LOG);
const minEdge = new Array(LOG);
for (let k = 0; k < LOG; k++) {
  up[k] = new Int32Array(N);
  minEdge[k] = new Int32Array(N);
}

const root = 0;
const stack = new Int32Array(N);
let stackSize = 0;
stack[stackSize++] = root;
up[0][root] = root;
minEdge[0][root] = 1000000007;

while (stackSize > 0) {
  const u = stack[--stackSize];
  for (let e = head[u]; e !== -1; e = next[e]) {
    const v = to[e];
    if (v === up[0][u] && u !== root) continue;
    if (v === root && u === root) continue;

    up[0][v] = u;
    minEdge[0][v] = weight[e];
    depth[v] = depth[u] + 1;
    stack[stackSize++] = v;
  }
}

for (let k = 1; k < LOG; k++) {
  const prevUp = up[k - 1];
  const currUp = up[k];
  const prevMin = minEdge[k - 1];
  const currMin = minEdge[k];

  for (let v = 0; v < N; v++) {
    const mid = prevUp[v];
    currUp[v] = prevUp[mid];
    currMin[v] = Math.min(prevMin[v], prevMin[mid]);
  }
}

const C = nextInt();
const output = new Array(C);

for (let i = 0; i < C; i++) {
  let x = nextInt() - 1;
  let y = nextInt() - 1;
  let answer = 1000000007;

  if (depth[x] < depth[y]) {
    const tmp = x;
    x = y;
    y = tmp;
  }

  let diff = depth[x] - depth[y];
  for (let k = LOG - 1; k >= 0; k--) {
    if ((diff & (1 << k)) !== 0) {
      answer = Math.min(answer, minEdge[k][x]);
      x = up[k][x];
    }
  }

  if (x !== y) {
    for (let k = LOG - 1; k >= 0; k--) {
      if (up[k][x] !== up[k][y]) {
        answer = Math.min(answer, minEdge[k][x], minEdge[k][y]);
        x = up[k][x];
        y = up[k][y];
      }
    }
    answer = Math.min(answer, minEdge[0][x], minEdge[0][y]);
  }

  output[i] = String(answer);
}

process.stdout.write(output.join('\n'));
